import itertools

import six

from .exceptions import FunctionNotReturningBoolean, ComparingNonListAgainstListOfQuery
from .message import NotFoundKey


def get_field_value(message, field_selector):
    """
    From message get value of field pointed by field_selector

    :param message: input of search
    :param field_selector: way of pointing the field
    :return: value of field or list of such values if field is nonunique
    :raises: :py:class:`ute_common_abstract_core.message.NotFoundKey`: If field can't be found
    """
    field_value = None
    pure_key_name = field_selector
    field_value_list = message.get_all_values_by_key(pure_key_name)
    if len(field_value_list) == 1:
        field_value = field_value_list[0]
    else:
        field_value = field_value_list
    return field_value


def get_value_comparator_function(left_function_value_accessor, operator, right_function_value_accessor):
    """

    :param left_function_value_accessor:
    :param operator: compare operator
    :param right_function_value_accessor:
    :return: compare funtion
    """
    operator2comparator = {
        '==': lambda left, right: left == right,
        'eq': lambda left, right: left == right,
        '!=': lambda left, right: left != right,
        'ne': lambda left, right: left != right,
        '>': lambda left, right: left > right,
        'gt': lambda left, right: left > right,
        '>=': lambda left, right: left >= right,
        'ge': lambda left, right: left >= right,
        '<': lambda left, right: left < right,
        'lt': lambda left, right: left < right,
        '<=': lambda left, right: left <= right,
        'le': lambda left, right: left <= right,
    }

    def compare(structure):
        """
        Compare field values

        :param structure: message
        :return: boolean
        """
        left_operand = left_function_value_accessor(structure)
        right_operand = right_function_value_accessor(structure)

        comparator = operator2comparator[operator]
        result = comparator(left_operand, right_operand)
        return result

    return compare


def get_field_value_access_function(field_selector):
    """

    :param field_selector: field name
    :return: function get_field
    """
    def get_field(structure):
        """
        Get field from structure

        :param structure: message
        :return: field value
        """
        return get_field_value(structure, field_selector)

    return get_field


def get_value_access_function(value):
    """

    :param value: value
    :return: function get_value
    """
    # we need structure only to have same format of all filter-functions
    def get_value(structure):  # pylint: disable=unused-argument
        """
        Get value

        :param structure: message
        :return: value
        """
        return value

    return get_value


def check_field_existence_function(field_selector, existence_operator):
    """

    :param field_selector:
    :param existence_operator:
    :return: function check
    """
    def check(structure):
        """
        Check if field is present in structure

        :param structure: message
        :return: boolean
        """
        try:
            get_field_value(structure, field_selector)
            result = existence_operator == 'is present'
        except NotFoundKey:
            result = existence_operator == 'is not present'
        return result

    return check


def get_function_on_field_function(field_value_access_function, registered_wrapped_function, registered_function_other_parameters):
    """

    :param field_value_access_function:
    :param registered_wrapped_function:
    :param registered_function_other_parameters:
    :return: function call_function_on_field
    """
    def call_function_on_field(structure):
        """

        :param structure: message
        :return: function call
        """
        substructure = field_value_access_function(structure)
        # FUNCTION_ON_FIELD_CALL operates on substructure pointed by FIELD_SELECTOR
        registered_function = registered_wrapped_function.__wrapped__  # retrieve function defined by user
        if six.get_function_code(registered_function).co_argcount == 1:
            return registered_function(substructure)
        return registered_function(substructure, registered_function_other_parameters)

    return call_function_on_field


def get_function_on_value_function(registered_wrapped_function, registered_function_parameter):
    """

    :param registered_wrapped_function:
    :param registered_function_parameter:
    :return: function call_function_on_value
    """
    # we need structure only to have same format of all filter-functions
    def call_function_on_value(structure):  # pylint: disable=unused-argument
        """

        :param structure: message
        :return: function call
        """
        registered_function = registered_wrapped_function.__wrapped__  # retrieve function defined by user
        if six.get_function_code(registered_function).co_argcount == 0:
            return registered_function()
        return registered_function(registered_function_parameter)

    return call_function_on_value


def get_fulfills_comparator(field_value_access_function, registered_wrapped_function, registered_function_other_parameters):
    """

    :param field_value_access_function:
    :param registered_wrapped_function:
    :param registered_function_other_parameters:
    :return:
    """
    call_function_on_field = get_function_on_field_function(field_value_access_function, registered_wrapped_function,
                                                            registered_function_other_parameters)

    def boolean_return_checker(structure):
        """

        :param structure: message
        :return:
        """
        result = call_function_on_field(structure)
        # FUNCTION_CALL of FULLFILLS operator should return boolean result
        if isinstance(result, bool):
            return result
        raise FunctionNotReturningBoolean(registered_wrapped_function.__wrapped__, result)

    fulfills = boolean_return_checker
    return fulfills


def f_or_and(left_operand_filter, logical_operator, right_operand_filter):
    """

    :param left_operand_filter:
    :param logical_operator:  'and' or 'or'
    :param right_operand_filter:
    :return:
    """
    def compare(structure):
        """

        :param structure: message
        :return: boolean
        """
        left_operand = left_operand_filter(structure)
        if logical_operator == 'and':
            result = (left_operand and right_operand_filter(structure)) if left_operand is True else left_operand
        else:
            result = (left_operand or right_operand_filter(structure)) if left_operand is False else left_operand
        return result

    return compare


def f_not(query_to_negate):
    """

    :param query_to_negate:
    :return:
    """
    def compare(structure):
        """

        :param structure: message
        :return: boolean
        """
        return not query_to_negate(structure)

    return compare


def get_contains_comparator(field_value_access_function, query_filter):
    """

    :param field_value_access_function:
    :param query_filter:
    :return: function contains
    """
    def contains(structure):
        """

        :param structure: message
        :return:
        """
        pointed_dict = field_value_access_function(structure)
        # query at rigth side of CONTAINS operates on substructure pointed by FIELD_SELECTOR
        return query_filter(pointed_dict)

    return contains


def get_contains_comparator_2(field_value_access_function, list_of_query_filters):
    """

    :param field_value_access_function:
    :param list_of_query_filters:
    :return: function contains
    """
    def contains(structure):
        """

        :param structure: message
        :return:
        """
        substructure = field_value_access_function(structure)
        if isinstance(substructure, list):
            q2v_index_mapping = queries_to_values_matching_algorithm(query_list=list_of_query_filters, value_list=substructure)
            field_contains_query_list = q2v_index_mapping != {}
            return field_contains_query_list
        if len(list_of_query_filters) > 1:
            raise ComparingNonListAgainstListOfQuery(substructure, list_of_query_filters)
        query_filter = list_of_query_filters[0]
        return query_filter(substructure)

    return contains


def _get_all_fulfilling_combinations(fulfilling_values_lists):
    return list(itertools.product(*fulfilling_values_lists))  # TODO: return iterator?


def _get_first_fulfilling_combination_of_different_values(fulfilling_values_lists):
    for combination in _get_all_fulfilling_combinations(fulfilling_values_lists):
        size_with_repetitions = len(combination)
        size_without_repetitions = len(set(combination))
        if size_with_repetitions == size_without_repetitions:
            return combination
    return None


def _has_fulfilling_combination_of_different_values(fulfilling_values_lists):
    combination = _get_first_fulfilling_combination_of_different_values(fulfilling_values_lists)
    if combination is not None:
        return True
    return False


def _prepare_search_progress_structure(query_list, value_list):
    """Each query may potentially be checked against each value."""
    search_progress = []
    value_index_to_check = list(range(len(value_list)))
    for _ in query_list:
        check_info = {'check_status': ["to_check" for _ in value_index_to_check],  # value_index is inside 'check_status' list
                      'found_idx': None,
                      'fulfilling_idxs': []}
        search_progress.append(check_info)  # query_index is inside search_progress list
    return search_progress


def _is_next_check_possible(search_progress):
    for query_idx, _ in enumerate(search_progress):
        if "to_check" in search_progress[query_idx]['check_status']:
            return True
    return False


def _never_checked_query(search_progress):
    for query_idx, _ in enumerate(search_progress):
        if "checked" not in search_progress[query_idx]['check_status']:  # checked against any value?
            return query_idx
    return None


def _not_fully_checked_query(search_progress):
    for query_idx, _ in enumerate(search_progress):
        if "to_check" in search_progress[query_idx]['check_status']:  # remaining check against some value
            return query_idx
    return None


def _never_checked_values(search_progress):
    never_checked_values = []
    if search_progress:
        query_indexes = list(range(len(search_progress)))
        check_status_per_value_idx = search_progress[0]['check_status']
        value_indexes = list(range(len(check_status_per_value_idx)))
        for value_idx in value_indexes:
            for query_idx in query_indexes:
                query_value_check_status = search_progress[query_idx]['check_status'][value_idx]
                if query_value_check_status == "checked":
                    break
            else:
                never_checked_values.append(value_idx)  # no query checked this value
    return never_checked_values


def _find_value_index_matching_query(query, value_list, values_indexes_to_check):
    v_index_found = None
    v_indexes_checked = []
    for v_idx in values_indexes_to_check:
        v_indexes_checked.append(v_idx)
        value = value_list[v_idx]
        try:
            if isinstance(value, int):
                if query(value) == value:
                    v_index_found = v_idx
                    break
                else:
                    continue
            if query(value):
                v_index_found = v_idx
                break
        except NotFoundKey:
            pass
    return v_index_found, v_indexes_checked


def _update_checked_value_status(search_progress, query_idx, checked_value_indexes):
    for v_idx in checked_value_indexes:
        search_progress[query_idx]['check_status'][v_idx] = 'checked'


def _not_checked_values_for_query(search_progress, query_idx):
    check_status_per_value_idx = search_progress[query_idx]['check_status']
    remaining_to_check = [v_idx for v_idx, check_status in enumerate(check_status_per_value_idx) if check_status == 'to_check']
    return remaining_to_check


def _get_fulfilling_values_per_query(search_progress):
    fulfilling_values_per_query = []
    for check_info in search_progress:
        fulfilling_values_per_query.append(check_info['fulfilling_idxs'])
    return fulfilling_values_per_query


def _query_fulfilled(search_progress, query_idx):
    check_info = search_progress[query_idx]
    if not check_info['fulfilling_idxs']:
        return False
    return True


def _all_queries_fulfilled(search_progress):
    for check_info in search_progress:
        if not check_info['fulfilling_idxs']:
            return False
    return True


# ToDo: mccabe report 14 - function should be simpler
def queries_to_values_matching_algorithm(query_list, value_list):  # Noqa: C901
    """
    Return dictionary showing which query is fulfilled by which value.
    If no mapping can be found - return empty dictionary.
    Keys are indexes from query list, values are indexes from value_list.
    """
    matching_indexes = {}
    if len(value_list) < len(query_list):
        return {}  # not enough values to fulfill all queries

    search_progress = _prepare_search_progress_structure(query_list, value_list)
    max_loop_iterations = 1000
    loop_iteration = 0

    next_check_possible = _is_next_check_possible(search_progress)
    while next_check_possible:
        loop_iteration += 1
        query_idx = _never_checked_query(search_progress)
        if query_idx is not None:
            never_checked_value_indexes = _never_checked_values(search_progress)
            value_indexes_to_check = never_checked_value_indexes
            if not value_indexes_to_check:
                value_indexes_remaining_to_check = _not_checked_values_for_query(search_progress, query_idx)
                value_indexes_to_check = value_indexes_remaining_to_check
            query = query_list[query_idx]
            v_idx_found, v_idx_checked = _find_value_index_matching_query(query, value_list, value_indexes_to_check)
            _update_checked_value_status(search_progress, query_idx, v_idx_checked)
            if v_idx_found is not None:
                search_progress[query_idx]['found_idx'] = v_idx_found
                search_progress[query_idx]['fulfilling_idxs'].append(v_idx_found)
            else:  # any remaining chances to make this query happy?
                value_indexes_remaining_to_check = _not_checked_values_for_query(search_progress, query_idx)
                if not value_indexes_remaining_to_check:
                    return {}  # at least single query is not satisfied by any value
        else:  # each query has been checked (but not against all values)
            query_idx = _not_fully_checked_query(search_progress)
            if query_idx is not None:
                never_checked_value_indexes = _never_checked_values(search_progress)
                value_indexes_to_check = never_checked_value_indexes
                if not value_indexes_to_check:
                    value_indexes_remaining_to_check = _not_checked_values_for_query(search_progress, query_idx)
                    value_indexes_to_check = value_indexes_remaining_to_check
                query = query_list[query_idx]
                v_idx_found, v_idx_checked = _find_value_index_matching_query(query, value_list, value_indexes_to_check)
                _update_checked_value_status(search_progress, query_idx, v_idx_checked)
                if v_idx_found is not None:
                    search_progress[query_idx]['found_idx'] = v_idx_found
                    search_progress[query_idx]['fulfilling_idxs'].append(v_idx_found)
                else:  # any remaining chances to make this query happy?
                    value_indexes_remaining_to_check = _not_checked_values_for_query(search_progress, query_idx)
                    if (not _query_fulfilled(search_progress, query_idx)) and (not value_indexes_remaining_to_check):
                        return {}  # at least single query is not satisfied by any value

        if _all_queries_fulfilled(search_progress):  # means all queries have been checked and each has some matching value
            fulfilling_values_per_query = _get_fulfilling_values_per_query(search_progress)
            fulfilling_values_combination = _get_first_fulfilling_combination_of_different_values(fulfilling_values_per_query)
            if fulfilling_values_combination is not None:
                matching_indexes = {query_idx: value_idx for query_idx, value_idx in enumerate(fulfilling_values_combination)}  # Noqa: C416
                return matching_indexes

        next_check_possible = _is_next_check_possible(search_progress)
        if loop_iteration > max_loop_iterations:
            break

    return matching_indexes
